// План specs/audit-log.md, 1.1 (кейс AL-01). Пользователь «בדיקה». Только чтение (GET). @prod-safe
import { test, expect } from '@playwright/test';
import { supabaseSession, readAuditLog } from './audit-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Audit log — RLS для не супер-админа (#fc4fa4)', () => {
  test('Regular user reading AuditLog directly via REST gets 200 and an empty list #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    const s = await supabaseSession(page);
    const { status, body } = await readAuditLog(page, s);
    // 200 + [] вместо 403 — принято (RLS на SELECT), решение 12.11
    expect(status, 'GET /rest/v1/AuditLog').toBe(200);
    expect(body, 'журнал закрыт RLS: 0 записей, включая свои').toEqual([]);
  });
});
